function nextStep(step) {
    document
        .querySelectorAll(".content")
        .forEach((c) => c.classList.add("hidden"));
    document.getElementById("step" + step).classList.remove("hidden");

    document.querySelectorAll(".step").forEach((s, i) => {
        s.classList.remove("active", "completed");
        if (i + 1 < step) {
            s.classList.add("completed");
        } else if (i + 1 === step) {
            s.classList.add("active");
        }
    });

    if (step === 2) {
        var frameBox = document.querySelectorAll(
            ".changeCustomVariant.FrameBx.active"
        );
        var topBox = document.querySelectorAll(
            ".changeCustomVariant.tableTopBx.active"
        );

        if (frameBox.length > 0) {
            var image = frameBox[0].dataset.img;
            document.querySelectorAll(".Tframe img")[0].src = image;
        }

        if (topBox.length > 0) {
            var image = topBox[0].dataset.img;
            document.getElementById("tableTop").src = image;
        }
    }
}

(() => {
    const holder = document.getElementById("holder");
    const deskImg = document.getElementById("deskImg");
    const ruler = document.getElementById("ruler");
    const wLabel = document.getElementById("wLabel");
    const dLabel = document.getElementById("dLabel");
    const options = document.querySelectorAll(".tableBx");
    const tableSec = document.querySelector("#holder .tableSec");
    const depthSec = document.getElementById("depth");
    const step1Desc = document.getElementById("step1-desc");

    const BASE_W = 120;
    const BASE_H = 75;
    const BASE_D = 60;
    const MAX_IMG_PCT = 0.88;

    // 👉 function that sets max height based on screen width
    function getMaxHolderHeight() {
        return window.innerWidth <= 768 ? 160 : 440;
    }

    let current = {
        w: Number(options[0].dataset.w),
        d: Number(options[0].dataset.d),
        h: Number(options[0].dataset.h),
        img: options[0].dataset.img,
        desc: options[0].dataset.desc,
    };

    function cmToPxWidth(cm) {
        const holderW = holder.clientWidth;
        const maxPx = holderW * MAX_IMG_PCT;
        return Math.max(220, (cm / BASE_W) * maxPx);
    }

    function render() {
        let imgWidthPx = cmToPxWidth(current.w);
        let imgHeightPx =
            (current.h / BASE_H) * (imgWidthPx * (BASE_H / BASE_W));

        const MAX_HOLDER_HEIGHT = getMaxHolderHeight(); // 🔥 responsive max height

        if (imgHeightPx > MAX_HOLDER_HEIGHT) {
            const scale = MAX_HOLDER_HEIGHT / imgHeightPx;
            imgHeightPx = MAX_HOLDER_HEIGHT;
            imgWidthPx = imgWidthPx * scale;
        }

        deskImg.style.width = imgWidthPx + "px";
        deskImg.style.height = imgHeightPx + "px";
        deskImg.src = current.img;

        tableSec.style.height = imgHeightPx + "px";
        holder.style.height = imgHeightPx + "px";

        ruler.style.width = imgWidthPx - 90 + "px";

        // Depth label
        dLabel.textContent = current.d + " cm";
        wLabel.textContent = `${current.w} cm`;

        step1Desc.textContent = current.desc;
    }

    function setActive(card) {
        options.forEach((c) => c.classList.remove("active"));
        card.classList.add("active");
    }

    options.forEach((card) => {
        card.addEventListener("click", () => {
            setActive(card);
            current = {
                w: Number(card.dataset.w),
                d: Number(card.dataset.d),
                h: Number(card.dataset.h),
                img: card.dataset.img,
                desc: card.dataset.desc,
            };
            render();
        });
    });

    window.addEventListener("resize", render);

    // setActive(options[0]);
    render();
})();

// stepper 2

const tableTopBx = document.querySelectorAll(".tableTopBx");
const frameBx = document.querySelectorAll(".FrameBx");

const topBox = document.querySelector(".topBxo");
const frameBox = document.querySelector(".Tframe");

const step2title = document.getElementById("step2title");

/* ====== TABLE TOP ====== */
let currentTopIndex = Array.from(tableTopBx).findIndex((el) =>
    el.classList.contains("active")
);
if (currentTopIndex < 0) currentTopIndex = 0;
let isTopAnimating = false;

tableTopBx.forEach((option, index) => {
    option.addEventListener("click", () => {
        if (isTopAnimating || index === currentTopIndex) return;
        isTopAnimating = true;

        tableTopBx.forEach((o) => o.classList.remove("active"));
        option.classList.add("active");

        const newSrc = option.dataset.img;
        const currentImg = topBox.querySelector(".table-top");
        const direction = index > currentTopIndex ? "forward" : "backward";

        const newImg = document.createElement("img");
        newImg.src = newSrc;
        newImg.alt = "Table Top";
        newImg.className = `table-top ${
            direction === "forward" ? "enter-up" : "enter-down"
        }`;
        topBox.appendChild(newImg);

        requestAnimationFrame(() => {
            currentImg.classList.add(
                direction === "forward" ? "exit-up" : "exit-down"
            );
            requestAnimationFrame(() => {
                newImg.classList.add("active");
            });
        });

        const onDone = (e) => {
            if (e.propertyName !== "transform") return;
            newImg.removeEventListener("transitionend", onDone);
            currentImg.remove();
            currentTopIndex = index;
            isTopAnimating = false;
        };
        newImg.addEventListener("transitionend", onDone);

        updateStep2Title();
    });
});
/* ====== TABLE FRAME (no animation) ====== */
frameBx.forEach((option) => {
    option.addEventListener("click", () => {
        frameBx.forEach((o) => o.classList.remove("active"));
        option.classList.add("active");

        const newSrc = option.dataset.img;
        frameBox.innerHTML = `<img src="${newSrc}" alt="Table Frame" class="table-frame">`;

        // updateSelectionTitle();
        updateStep2Title();
    });
});

function updateStep2Title() {
    const topTitle = Array.from(tableTopBx).find((el) =>
        el.classList.contains("active")
    )?.dataset.name;
    const frameTitle = Array.from(frameBx).find((el) =>
        el.classList.contains("active")
    )?.dataset.name;
    if (frameTitle === undefined) step2title.textContent = topTitle;
    else step2title.textContent = `${topTitle} & ${frameTitle}`;
}
